<?php
require_once __DIR__ . '/../config/database.php';require_once __DIR__ . '/../helpers/auth.php';require_login();require_once __DIR__ . '/../helpers/escape.php';require_once __DIR__ . '/../helpers/csrf.php';
$pageTitle='Transaksi Stok';$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pid=filter_var($_POST['product_id']??null,FILTER_VALIDATE_INT);$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$type=$_POST['type']??'';$note=trim($_POST['note']??'');
 if(!$pid||!$qty||$qty<1||!in_array($type,['IN','OUT'],true))$error='Produk, jenis transaksi, dan jumlah harus diisi dengan benar.';
 else{try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT id,stock FROM products WHERE id=? FOR UPDATE');$st->execute([$pid]);$product=$st->fetch();if(!$product)throw new RuntimeException('Produk tidak ditemukan.');if($type==='OUT'&&$qty>(int)$product['stock'])throw new RuntimeException('Stok tidak cukup untuk transaksi barang keluar.');$newStock=$type==='IN'?(int)$product['stock']+$qty:(int)$product['stock']-$qty;$pdo->prepare('UPDATE products SET stock=? WHERE id=?')->execute([$newStock,$pid]);$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,type,quantity,note) VALUES(?,?,?,?,?)')->execute([$pid,$_SESSION['user']['id'],$type,$qty,$note]);$pdo->commit();$message='Transaksi berhasil disimpan dan stok sudah diperbarui.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Transaksi gagal disimpan.';}}
}
$products=$pdo->query('SELECT id,sku,name,stock FROM products ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT sm.*,p.name product_name,p.sku,u.username FROM stock_movements sm JOIN products p ON p.id=sm.product_id JOIN users u ON u.id=sm.user_id ORDER BY sm.id DESC LIMIT 100')->fetchAll();require '_header.php';
?>
<h1>Transaksi Barang</h1><p class="muted">Setiap transaksi memperbarui stok dan menyimpan histori secara bersamaan.</p><?php if($message):?><div class="notice"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?>
<div class="card"><h2>Catat Barang Masuk / Keluar</h2><?php if(!$products):?><p>Tambahkan produk terlebih dahulu.</p><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Produk</label><select name="product_id" required><?php foreach($products as $p):?><option value="<?=e($p['id'])?>"><?=e($p['sku'].' - '.$p['name'].' (stok: '.$p['stock'].')')?></option><?php endforeach;?></select><label>Jenis transaksi</label><select name="type"><option value="IN">Barang masuk</option><option value="OUT">Barang keluar</option></select><label>Jumlah</label><input type="number" name="quantity" min="1" required><label>Catatan</label><input name="note" maxlength="255"><div class="actions"><button>Simpan transaksi</button></div></form><?php endif;?></div>
<div class="card"><h2>Histori Transaksi (100 terbaru)</h2><div class="table-wrap"><table><tr><th>Waktu</th><th>SKU</th><th>Produk</th><th>Jenis</th><th>Jumlah</th><th>Pengguna</th><th>Catatan</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['sku'])?></td><td><?=e($r['product_name'])?></td><td><?=e($r['type']==='IN'?'Masuk':'Keluar')?></td><td><?=e($r['quantity'])?></td><td><?=e($r['username'])?></td><td><?=e($r['note'])?></td></tr><?php endforeach;?></table></div></div>
<?php require '_footer.php';?>
